changeSet.sql:
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_devices ENABLE ROW LEVEL SECURITY;

changeSet.rollback:
ALTER TABLE users DISABLE ROW LEVEL SECURITY;
ALTER TABLE oauth_accounts DISABLE ROW LEVEL SECURITY;
ALTER TABLE user_devices DISABLE ROW LEVEL SECURITY;

changeSet.sql:
CREATE POLICY clubs_select_visible ON clubs
    FOR SELECT
    USING (
        visibility = 'public'
        OR created_by_user_id = auth.uid()
        OR id IN (
            SELECT club_id FROM club_memberships
            WHERE status = 'active'
              AND player_id IN (
                  SELECT id FROM player_profiles WHERE user_id = auth.uid()
              )
        )
    );

CREATE POLICY clubs_insert_own ON clubs
    FOR INSERT
    WITH CHECK (created_by_user_id = auth.uid());

CREATE POLICY club_memberships_select_own ON club_memberships
    FOR SELECT
    USING (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    );

CREATE POLICY club_memberships_insert_own ON club_memberships
    FOR INSERT
    WITH CHECK (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
        AND (
            -- Creating your own club: you become OWNER, active, immediately.
            (role = 'OWNER' AND status = 'active'
                AND club_id IN (SELECT id FROM clubs WHERE created_by_user_id = auth.uid()))
            -- Requesting to join someone else's club: always starts pending.
            OR (role = 'MEMBER' AND status = 'pending')
        )
    );

CREATE POLICY club_memberships_update_own_leave ON club_memberships
    FOR UPDATE
    USING (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    )
    WITH CHECK (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
        AND status = 'left'
    );

changeSet.rollback:
DROP POLICY IF EXISTS club_memberships_select_own ON club_memberships;
DROP POLICY IF EXISTS club_memberships_insert_own ON club_memberships;
DROP POLICY IF EXISTS club_memberships_update_own_leave ON club_memberships;

changeSet.sql:
CREATE OR REPLACE FUNCTION fn_is_club_creator(target_club_id uuid)
RETURNS boolean
LANGUAGE sql SECURITY DEFINER STABLE
SET search_path = public
AS $$
    SELECT EXISTS (
        SELECT 1 FROM clubs WHERE id = target_club_id AND created_by_user_id = auth.uid()
    );
$$;

DROP POLICY IF EXISTS clubs_select_visible ON clubs;
CREATE POLICY clubs_select_visible ON clubs
    FOR SELECT
    USING (
        visibility = 'public'
        OR created_by_user_id = auth.uid()
        OR fn_is_active_club_member(id)
    );

changeSet.rollback:
DROP POLICY IF EXISTS clubs_select_visible ON clubs;
CREATE POLICY clubs_select_visible ON clubs
    FOR SELECT
    USING (
        visibility = 'public'
        OR created_by_user_id = auth.uid()
        OR id IN (
            SELECT club_id FROM club_memberships
            WHERE status = 'active'
              AND player_id IN (
                  SELECT id FROM player_profiles WHERE user_id = auth.uid()
              )
        )
    );

changeSet.sql:
DROP POLICY IF EXISTS club_memberships_insert_own ON club_memberships;
CREATE POLICY club_memberships_insert_own ON club_memberships
    FOR INSERT
    WITH CHECK (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
        AND (
            (role = 'OWNER' AND status = 'active' AND fn_is_club_creator(club_id))
            OR (role = 'MEMBER' AND status = 'pending')
        )
    );

